const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));let selected=null,selectedLevel=null;const tournamentRank=t=>{const n=String(t).toLowerCase();const order=['open','women','groms','infinity race','surf & dirt','legends','chair race','2 hour relay race'];const i=order.indexOf(n);return i<0?100:i};const navigationStage=e=>{const n=[e.stage,e.name,e.level].filter(Boolean).join(' ').toLowerCase();if(n.includes('qual'))return 'Qualifiers';if(n.includes('heat'))return 'Heats';if(n.includes('quarter'))return 'Quarters';if(n.includes('semi'))return 'Semi';if(n.includes('final'))return 'Finals';return 'Qualifiers'};const levelRank=level=>['Qualifiers','Heats','Quarters','Semi','Finals'].indexOf(level);async function get(u){const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw Error();return r.json()}function table(e,r){const timeLabel=e.multi_lap?'Fastest lap':'Time';return `<article class="race-table"><header><div><span>${esc(e.multi_lap?'Fastest lap':'Results')}</span><h3>${esc(e.name)}</h3></div><b>${r.length} riders</b></header><div class="table-scroll"><table><thead><tr><th>Pos</th><th>Rider</th><th>${timeLabel}</th></tr></thead><tbody>${r.map((x,i)=>`<tr class="${i<3?'podium':''}"><td class="place">${x.position}</td><td><a class="rider rider-link" href="/rider/?id=${encodeURIComponent(x.athlete_id)}"><span class="bib">${esc(x.bib)}</span><span class="name">${esc(x.name)}</span></a></td><td class="time">${esc(x.time)}</td></tr>`).join('')}</tbody></table></div></article>`}async function render(){try{const f=await get('/api/public/events');$('#status-badge').textContent=f.status;const ts=[...new Set(f.events.map(e=>e.tournament||'Tournament'))].sort((a,b)=>tournamentRank(a)-tournamentRank(b)||a.localeCompare(b));if(!selected||!ts.includes(selected))selected=ts[0];$('#event-tabs').innerHTML=ts.map(t=>`<button class="tab ${t===selected?'active':''}" data-t="${esc(t)}">${esc(t)}</button>`).join('');$('#event-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.t;selectedLevel=null;render()});const es=f.events.filter(e=>(e.tournament||'Tournament')===selected);if(!es.length){$('#race-title').textContent='No published results';return}const data=await Promise.all(es.map(e=>get('/api/public/events/'+encodeURIComponent(e.id)+'/results'))),levels=[...new Set(es.map(navigationStage))].sort((a,b)=>levelRank(a)-levelRank(b));if(!selectedLevel||!levels.includes(selectedLevel))selectedLevel=levels[0];$('#race-title').textContent=selected;$('#result-count').textContent=`${es.length} ${es.length===1?'race':'races'}`;$('#round-nav').innerHTML=levels.map((level,i)=>`<button class="round ${level===selectedLevel?'active':''}" data-level="${esc(level)}"><span class="round-name">${esc(level)}</span><span class="round-step">${i+1}</span></button>`).join('');$('#round-nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedLevel=b.dataset.level;render()});const set=es.map((e,i)=>({e,r:data[i]})).filter(x=>navigationStage(x.e)===selectedLevel);$('#stage-results').innerHTML=`<div class="race-grid ${set.length===1?'single':''}">${set.map(x=>table(x.e,x.r)).join('')}</div><p class="stage-note">Select any rider to see every recorded time and the race it came from.</p>`}catch{$('#race-title').textContent='Waiting for timing feed';$('#result-count').textContent='The live results service is not connected yet.'}}render();setInterval(render,15000);


